    public static int pbr_pbr_program_attr_slot(string attr_name) {
        if (attr_name == "position") {
            return 0;
        }
        if (attr_name == "normal") {
            return 1;
        }
        if (attr_name == "texcoord_0") {
            return 2;
        }
        if (attr_name == "tangent") {
            return 3;
        }
        if (attr_name == "in_model_0") {
            return 4;
        }
        if (attr_name == "in_model_1") {
            return 5;
        }
        if (attr_name == "in_model_2") {
            return 6;
        }
        if (attr_name == "in_model_3") {
            return 7;
        }
        if (attr_name == "in_custom") {
            return 8;
        }
        if (attr_name == "texcoord_1") {
            return 9;
        }
        return -1;
    }
    public static int pbr_pbr_program_texture_slot(string tex_name) {
